questions.solution:
function formatDuration(minutes) {
  const hours = Math.floor(minutes / 60);
  const rest = minutes % 60;
  return `${hours}h ${rest}m`;
}

console.log(formatDuration(135));
console.log(formatDuration(59));
console.log(formatDuration(120));

