questions.solution:
function canEdit(user, task) {
  return (user.name === task.owner && !task.done) || user.isAdmin === true;
}

const task = { owner: "ada", done: false };
const doneTask = { owner: "ada", done: true };

console.log(
  canEdit({ name: "ada", isAdmin: false }, task),
  canEdit({ name: "ada", isAdmin: false }, doneTask),
  canEdit({ name: "sam", isAdmin: true }, doneTask),
  canEdit({ name: "sam", isAdmin: false }, task),
);

